/** Every feature key in CSS_SUPPORT, as a type. */
export type FeatureKey =
  | (typeof HTML_ELEMENT_FEATURES)[number]
  | (typeof HTML_ATTRIBUTE_FEATURES)[number]
  | (typeof HTML_MISC_FEATURES)[number]
  | (typeof AT_RULE_FEATURES)[number]
  | (typeof COMPOUND_VALUE_FEATURES)[number]
  | (typeof SELECTOR_FEATURES)[number]
  | (typeof CSS_FUNCTION_FEATURES)[number]
  | (typeof CSS_PROPERTY_FEATURES)[number]
;

/** One feature key from each lane, for typing that lane's detectors. */
export type HtmlElementFeature = (typeof HTML_ELEMENT_FEATURES)[number];
export type HtmlAttributeFeature = (typeof HTML_ATTRIBUTE_FEATURES)[number];
export type HtmlMiscFeature = (typeof HTML_MISC_FEATURES)[number];
export type AtRuleFeature = (typeof AT_RULE_FEATURES)[number];

/** An image format caniemail grades. */
export type ImageFormat = (typeof IMAGE_FORMATS)[number];

/** A client the matrix answers for. */
export type ClientId = (typeof SUPPORT_CLIENTS)[number];

